/**
 * Versioned metadata for a selected runtime-native player.
 */
typedef struct NuxPlayerInfo {
  /**
   * Must be initialized to `sizeof(NuxPlayerInfo)` by the caller.
   */
  uint32_t struct_size;
  NuxPlayerKind kind;
  /**
   * Authored index within the selected kind, or `SIZE_MAX` for static.
   */
  size_t index;
  /**
   * Copied UTF-8 metadata owned by `NuxPlayer`; valid until player free.
   */
  struct NuxStringView name;
} NuxPlayerInfo;

typedef struct NuxPlayerInputChange {
  /**
   * One of the `NuxPlayerInputKind` constants. Stored as an integer so an
   * invalid C bit pattern is rejected rather than becoming a Rust enum.
   */
  uint32_t kind;
  struct NuxStringView name;
  /**
   * Canonical C boolean encoding: exactly 0 or 1. Other values reject the
   * whole batch before mutation.
   */
  uint32_t bool_value;
  float number_value;
} NuxPlayerInputChange;

typedef struct NuxPlayerPointerEvent {
  /**
   * One of the `NuxPlayerPointerKind` constants. Invalid values are
   * rejected during whole-batch validation.
   */
  uint32_t kind;
  float x;
  float y;
  int32_t pointer_id;
  float timestamp_seconds;
} NuxPlayerPointerEvent;

/**
 * One atomic, product-neutral player operation. Input and pointer arrays use
 * ABI-v3 fixed element strides; future element layouts require a new entry
 * point rather than appending fields and silently changing array stride.
 */
typedef struct NuxPlayerStep {
  uint32_t struct_size;
  const struct NuxPlayerInputChange *inputs;
  size_t input_count;
  const struct NuxPlayerPointerEvent *pointers;
  size_t pointer_count;
  float elapsed_seconds;
  /**
   * Opaque caller identity copied into runtime-authored change entries.
   */
  uint64_t correlation_id;
} NuxPlayerStep;

/**
 * Owned reported-event projection. All string views borrow the owning step
 * result and remain valid until its successful free.
 */
typedef struct NuxPlayerEventView {
  uint32_t struct_size;
  size_t event_local_index;
  uint32_t event_core_type;
  struct NuxStringView name;
  struct NuxStringView url;
  struct NuxStringView target;
  float seconds_delay;
  size_t property_count;
} NuxPlayerEventView;

/**
 * Fixed projection of one typed custom Event property. Only the value field
 * selected by `kind` is meaningful.
 */
typedef struct NuxPlayerEventPropertyView {
  uint32_t struct_size;
  /**
   * One of the `NUX_PLAYER_EVENT_PROPERTY_KIND_*` constants.
   */
  uint32_t kind;
  struct NuxStringView name;
  float number_value;
  bool bool_value;
  /**
   * Exact authored/script bytes for a String property; not necessarily UTF-8.
   */
  struct NuxByteView string_value;
  uint32_t color_value;
  uint64_t integer_value;
} NuxPlayerEventPropertyView;

/**
 * One command in transaction FIFO order. `root_value_index` addresses the
 * owning step result's flattened value graph.
 */
typedef struct NuxHostCommandView {
  uint32_t struct_size;
  struct NuxStringView name;
  size_t root_value_index;
} NuxHostCommandView;

/**
 * One flattened host value. Scalars use their matching value field. Lists
 * and objects expose `child_count` edges through
 * `nux_player_step_result_host_value_child`.
 */
typedef struct NuxHostValueView {
  uint32_t struct_size;
  uint32_t kind;
  bool bool_value;
  double number_value;
  struct NuxStringView string_value;
  size_t child_count;
} NuxHostValueView;

/**
 * One edge in a list or object. Object edges have a present UTF-8 `key`;
 * list edges use NULL+0. `value_index` addresses the same owned result.
 */
typedef struct NuxHostValueChildView {
  uint32_t struct_size;
  struct NuxStringView key;
  size_t value_index;
} NuxHostValueChildView;

/**
 * Summary of one owned step result. `keep_going` is the runtime's
 * advanceAndApply continuation result; it is not a host render/scheduling
 * request.
 */
typedef struct NuxPlayerStepInfo {
  uint32_t struct_size;
  bool keep_going;
  size_t pointer_result_count;
  size_t state_change_count;
  size_t event_count;
  /**
   * Commands are exposed only after the transaction commits. Hosts copy
   * authored events first, then commands in FIFO order.
   */
  size_t host_command_count;
  size_t view_model_change_count;
} NuxPlayerStepInfo;

/**
 * Product-neutral scheduling facts captured by one successful atomic player
 * step. They are deliberately independent from `keep_going`, whose meaning
 * remains the exact pinned C++ `advanceAndApply` return value.
 */
typedef struct NuxPlayerSchedulingInfo {
  uint32_t struct_size;
  /**
   * This committed operation changed observable runtime state.
   */
  bool dirty;
  /**
   * No selected root or nested runtime occurrence needs continuation.
   */
  bool settled;
  /**
   * The current occurrence revision has not yet been presented.
   */
  bool render_required;
  /**
   * Whether `wake_deadline_monotonic_ns` contains a deadline.
   */
  bool has_wake_deadline;
  /**
   * Clock whose epoch defines `wake_deadline_monotonic_ns`.
   */
  NuxMonotonicClockDomain wake_deadline_clock;
  /**
   * Exact occurrence-local revision associated with `render_required`.
   */
  uint64_t render_revision;
  /**
   * Absolute nanoseconds in `wake_deadline_clock`'s named domain.
   * The current runtime has no time-based deferred work and reports this
   * field absent rather than manufacturing a host-policy deadline.
   */
  uint64_t wake_deadline_monotonic_ns;
} NuxPlayerSchedulingInfo;

/**
 * C++ `stateChangedByIndex` projection in compressed authored-layer order.
 */
typedef struct NuxPlayerStateChangeView {
  uint32_t struct_size;
  size_t layer_index;
  /**
   * Pinned Core schema type key (`Core::typeKey`).
   */
  uint32_t state_core_type;
  /**
   * Authored Core id, or `UINT32_MAX` when absent.
   */
  uint32_t state_global_id;
} NuxPlayerStateChangeView;

/**
 * One ordered after-value from an owned mutation or player-step result.
 * Every borrowed field expires when that containing result is freed.
 */
typedef struct NuxViewModelChangeView {
  uint32_t struct_size;
  uint32_t origin;
  uint64_t correlation_id;
  uint64_t owner_instance_id;
  size_t property_index;
  uint32_t kind;
  /**
   * String after-value bytes borrowed from the containing result.
   * Absent for other value kinds.
   */
  struct NuxByteView bytes_value;
  float number_value;
  uint64_t integer_value;
  uint32_t bool_value;
  uint64_t referenced_instance_id;
  size_t list_item_count;
} NuxViewModelChangeView;

/**
 * Native TextInput geometry for an exact presented semantic occurrence.
 * The transform maps input-local coordinates into the root artboard, including
 * nested placement. Bounds describe shaped text, NOT the field container;
 * When present, layout_ancestor_* supplies the affine field layout box.
 * Semantic bounds describe an axis-aligned interaction box, not local layout.
 * Contains no editable text, glyph identifiers, or native selection state.
 * With a host-owned content ScrollConstraint, geometry is the unscrolled
 * editing basis and layout_ancestor_* is its stationary viewport. Native
 * editors apply their own content offset; feeding it back here would scroll
 * the UIKit control a second time.
 */
typedef struct NuxTextInputGeometry {
  uint32_t struct_size;
  uint64_t render_revision;
  float world_transform[6];
  float min_x;
  float min_y;
  float max_x;
  float max_y;
  uint32_t has_first_baseline;
  float first_baseline;
  uint32_t obscured;
  uint32_t multiline;
  /**
   * Nearest layout ancestor, in its own local coordinates. The transform
   * includes nested occurrence placement; semantic bounds are only an AABB.
   */
  uint32_t has_layout_ancestor;
  float layout_ancestor_transform[6];
  float layout_ancestor_min_x;
  float layout_ancestor_min_y;
  float layout_ancestor_max_x;
  float layout_ancestor_max_y;
} NuxTextInputGeometry;

/**
 * Copied geometry; never contains text, glyphs, or pointers into the scene.
 * Matrices use [a, b, c, d, tx, ty]: x' = a*x + c*y + tx.
 * `world_transform` maps the text's local layout box into artboard space.
 * `content_transform` additionally includes runtime text fitting/alignment.
 * Bounds are the local layout box, including authored origin/baseline offset;
 * they are not the ink bounds and must use `world_transform`.
 */
typedef struct NuxTextRunGeometry {
  uint32_t struct_size;
  uint64_t render_revision;
  float world_transform[6];
  float content_transform[6];
  float min_x;
  float min_y;
  float max_x;
  float max_y;
  /**
   * Canonical 0/1. Zero means there is no LayoutComponent ancestor.
   */
  uint32_t has_layout_ancestor;
  /**
   * Nearest LayoutComponent ancestor, excluding the text itself. All fields
   * below are zero when absent. This is a structural relationship, not a
   * semantic field association or an axis-aligned world bounding box.
   */
  float layout_ancestor_transform[6];
  float layout_ancestor_min_x;
  float layout_ancestor_min_y;
  float layout_ancestor_max_x;
  float layout_ancestor_max_y;
  /**
   * Canonical 0/1. Empty or unshaped text has no first baseline.
   */
  uint32_t has_first_baseline;
  /**
   * First logical line's baseline y in shaped-content coordinates. Map
   * through content_transform; zero when has_first_baseline is zero.
   */
  float first_baseline;
} NuxTextRunGeometry;

typedef void (*NuxVideoCaptionCallback)(void*, struct NuxStringView, struct NuxStringView);

/**
 * One event consumed from the occurrence's shared event queue. State=0
 * (`state` uses NuxVideoInfo's values), first-frame=1, looped=2,
 * play-blocked=3, error=4, resource-limited=5 (`state` is 1 when limited, 0
 * when restored). Luau nextEvent and this API consume the same queue;
 * hosts should select one event owner and fan out notifications themselves.
 */
typedef struct NuxVideoEvent {
  uint32_t kind;
  uint32_t state;
} NuxVideoEvent;

/**
 * Top-row-first opaque SDR RGBA8, or premultiplied RGBA8 sRGB. Caller storage
 * is borrowed for this call only; the renderer owns the uploaded frame.
 */
typedef struct NuxVideoFrame {
  uint32_t struct_size;
  uint64_t generation;
  double presentation_seconds;
  uint32_t width;
  uint32_t height;
  uint32_t row_bytes;
  struct NuxByteView pixels;
} NuxVideoFrame;

/**
 * Current native media clock, in the same order as group creation. Mark an
 * unavailable/seeking clock available=0. Boolean fields must be 0 or 1.
 * A stale generation is ignored; never supply a decoded frame PTS here.
 */
typedef struct NuxVideoClockSample {
  uint64_t generation;
  double seconds;
  double rate;
  uint32_t playing;
  uint32_t available;
} NuxVideoClockSample;

/**
 * Plain text cue; [start,end) is in the video's media timeline. Text is copied
 * during installation. Markup interpretation belongs to the caption importer.
 */
typedef struct NuxVideoCaptionCue {
  double start_seconds;
  double end_seconds;
  struct NuxStringView text;
} NuxVideoCaptionCue;

/**
 * One decoder action. Play=0, pause=1, seek=2, rate=3, volume=4,
 * dispose=5. `value` is seconds/rate/volume; seek carries the new generation.
 */
typedef struct NuxVideoAction {
  uint32_t kind;
  double value;
  uint64_t generation;
} NuxVideoAction;

typedef void (*NuxVideoActionCallback)(void*, const struct NuxVideoAction*);

/**
 * All views passed to this callback are valid only during the callback.
 * Copy source strings/embedded bytes before returning if retaining them.
 */
typedef struct NuxVideoInfo {
  uint32_t struct_size;
  size_t component_id;
  uint32_t asset_id;
  uint64_t generation;
  /**
   * Opening=0, ready=1, playing=2, paused=3, seeking=4, buffering=5,
   * ended=6, failed=7, disposed=8.
   */
  uint32_t state;
  double position_seconds;
  float volume;
  float rate;
  uint32_t muted;
  uint32_t wants_play;
  uint32_t audio_policy;
  struct NuxStringView source_key;
  struct NuxStringView content_type;
  struct NuxByteView embedded_bytes;
  /**
   * Authored component name in this player's artboard. Names may be empty or
   * repeated; hosts must reject ambiguous named targets rather than selecting
   * the first match. The view is borrowed for the duration of the callback.
   */
  struct NuxStringView component_name;
  /**
   * Higher priorities win when a host cannot admit every visible decoder.
   */
  uint32_t priority;
  /**
   * Show immediately with poster=0, wait for first frame=1.
   */
  uint32_t readiness;
  /**
   * Definition artboard index in the imported file, not a mounted-instance index.
   */
  size_t source_artboard_index;
  /**
   * Definition-local slot used by the signed authored-target inventory.
   */
  size_t source_component_id;
} NuxVideoInfo;

typedef void (*NuxVideoInfoCallback)(void*, const struct NuxVideoInfo*);

